import{_ as e,C as i,c as n,o as r,a0 as t,b as s,w as l,a,G as o,a1 as h}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Zielsetzung für Pétanque-Spieler","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/goals/index.md","filePath":"de/education/goals/index.md"}');const d=e({name:"de/education/goals/index.md"},[["render",function(e,u,d,c,g,b){const m=i("Mermaid");return r(),n("div",null,[u[1]||(u[1]=t('<h1 id="zielsetzung-fur-petanque-spieler" tabindex="-1">Zielsetzung für Pétanque-Spieler <a class="header-anchor" href="#zielsetzung-fur-petanque-spieler" aria-label="Permalink to &quot;Zielsetzung für Pétanque-Spieler&quot;">​</a></h1><p>Klare Ziele sind dein Kompass. Sie geben deinem Training Richtung, motivieren dich in schwierigen Phasen und ermöglichen es dir, deine Fortschritte zu messen. Ohne Ziele wirfst du planlos Bälle. Mit Zielen arbeitest du auf etwas hin.</p><div class="tip custom-block"><p class="custom-block-title">Das Kernprinzip</p><p><strong>Ein Ziel ohne Plan ist nur ein Wunsch.</strong> Setzen Sie sich klare Ziele, unterteilen Sie diese in kleinere Schritte, konzentrieren Sie sich auf das, was Sie kontrollieren können, und verfolgen Sie Ihre Fortschritte.</p></div><h2 id="warum-ziele-wichtig-sind" tabindex="-1">Warum Ziele wichtig sind <a class="header-anchor" href="#warum-ziele-wichtig-sind" aria-label="Permalink to &quot;Warum Ziele wichtig sind&quot;">​</a></h2><p>Ziele erfüllen mehrere Zwecke:</p><ul><li><strong>Anleitung:</strong> Wissen, woran man arbeiten soll</li><li><strong>Motivation:</strong> Ein Ziel haben, nach dem man streben kann</li><li><strong>Messung:</strong> Verfolgen Sie Ihren Fortschritt</li><li><strong>Fokus:</strong> Priorisieren Sie Ihre begrenzte Zeit</li></ul><p>Für den selbstmotivierten Spieler sind Ziele besonders wichtig. Ohne einen Trainer, der einen antreibt, werden die eigenen Ziele zum Leitfaden.</p><h2 id="die-drei-zielarten" tabindex="-1">Die drei Zielarten <a class="header-anchor" href="#die-drei-zielarten" aria-label="Permalink to &quot;Die drei Zielarten&quot;">​</a></h2><p>Nicht alle Ziele sind gleichwertig. Wenn man die verschiedenen Zieltypen versteht, kann man bessere Ziele setzen.</p><h3 id="_1-ergebnisziele" tabindex="-1">1. Ergebnisziele <a class="header-anchor" href="#_1-ergebnisziele" aria-label="Permalink to &quot;1. Ergebnisziele&quot;">​</a></h3><p><strong>Was:</strong> Das gewünschte Endergebnis <strong>Beispiel:</strong> „Die Regionalmeisterschaft gewinnen“ <strong>Kontrollniveau:</strong> Niedrig – abhängig von Gegnern, Bedingungen und Glück</p><h3 id="_2-leistungsziele" tabindex="-1">2. Leistungsziele <a class="header-anchor" href="#_2-leistungsziele" aria-label="Permalink to &quot;2. Leistungsziele&quot;">​</a></h3><p><strong>Was:</strong> Spezifische Leistungsstandards <strong>Beispiel:</strong> „Erreiche eine Trefferquote von 80 % bei Schießübungen“ <strong>Kontrollgrad:</strong> Mittel – hängt größtenteils von Ihnen ab.</p><h3 id="_3-prozessziele" tabindex="-1">3. Prozessziele <a class="header-anchor" href="#_3-prozessziele" aria-label="Permalink to &quot;3. Prozessziele&quot;">​</a></h3><p><strong>Was:</strong> Handlungen und Verhaltensweisen, die Sie kontrollieren <strong>Beispiel:</strong> „Führe meine Vorbereitungsroutine vor jedem Wurf durch.“ <strong>Kontrollgrad:</strong> Hoch – Sie haben die volle Kontrolle.</p><h3 id="die-zielhierarchie" tabindex="-1">Die Zielhierarchie <a class="header-anchor" href="#die-zielhierarchie" aria-label="Permalink to &quot;Die Zielhierarchie&quot;">​</a></h3>',16)),(r(),s(h,null,{default:l(()=>[o(m,{id:"mermaid-69",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BErgebnisziel%20%3Cbr%2F%3E%20Der%20Traum%5D%20--%3E%20B%5BLeistungsziele%20%3Cbr%2F%3E%20Meilensteine%5D%0A%20%20%20%20B%20--%3E%20C%5BProzessziele%20%3Cbr%2F%3E%20T%C3%A4gliche%20Aktivit%C3%A4ten%5D%0A%0A%20%20%20%20A2%5B%26quot%3BRegionalmeisterschaft%20gewinnen%26quot%3B%5D%20--%3E%20B2%5B%26quot%3B80%25%20Treffsicherheit%26quot%3B%5D%0A%20%20%20%20B2%20--%3E%20C2%5B%E2%80%9EVollst%C3%A4ndige%20Vorbereitungsroutine%20vor%20der%20Impfung%E2%80%9C%20%3Cbr%2F%3E%20%E2%80%9Ejeder%20Wurf%E2%80%9C%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B%20fill%3A%23fff9c4%0A%20%20%20%20style%20C%20fill%3A%23c8e6c9%0A%20%20%20%20style%20A2%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B2%20fill%3A%23fff9c4%0A%20%20%20%20style%20C2%20fill%3A%23c8e6c9%0A"})]),fallback:l(()=>[...u[0]||(u[0]=[a(" Loading... ",-1)])]),_:1})),u[2]||(u[2]=t('<div class="warning custom-block"><p class="custom-block-title">Wichtigste Erkenntnis</p><p><strong>Konzentrieren Sie sich vor allem auf die Prozessziele.</strong> Diese haben Sie unter Kontrolle und sie führen zu den gewünschten Ergebnissen.</p><ul><li><strong>Ergebnisziele:</strong> Geringe Kontrolle, hohe Motivation</li><li><strong>Leistungsziele:</strong> Mittlere Kontrolle, messbarer Fortschritt</li><li><strong>Prozessziele:</strong> Hohe Kontrolle, täglicher Fokus ← <strong>Fokus hier</strong></li></ul></div><h2 id="das-smart-framework" tabindex="-1">Das SMART-Framework <a class="header-anchor" href="#das-smart-framework" aria-label="Permalink to &quot;Das SMART-Framework&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">SMART-Ziele-Checkliste</p><p>Jedes Ziel sollte sein:</p><ul><li>✅ <strong>Spezifisch</strong> – Klar und präzise definiert</li><li>✅ <strong>Messbar</strong> – Sie können Ihren Fortschritt verfolgen</li><li>✅ <strong>Erreichbar</strong> – anspruchsvoll, aber möglich</li><li>✅ <strong>R</strong>relevant – auf Ihr übergeordnetes Ziel ausgerichtet</li><li>✅ <strong>Zeitgebunden</strong> - Hat eine Frist</li></ul></div><h3 id="s-spezifisch" tabindex="-1">S - Spezifisch <a class="header-anchor" href="#s-spezifisch" aria-label="Permalink to &quot;S - Spezifisch&quot;">​</a></h3><p>❌ &quot;Verbessere deine Schießkünste&quot; ✅ „Meine Treffsicherheit bei Direktschüssen aus 8 Metern Entfernung verbessern“</p><h3 id="m-–-messbar" tabindex="-1">M – Messbar <a class="header-anchor" href="#m-–-messbar" aria-label="Permalink to &quot;M – Messbar&quot;">​</a></h3><p>❌ „Genauer schießen“ ✅ „Erreiche mindestens 24 von 30 Punkten bei der Schießleiterübung“</p><h3 id="a-–-erreichbar" tabindex="-1">A – Erreichbar <a class="header-anchor" href="#a-–-erreichbar" aria-label="Permalink to &quot;A – Erreichbar&quot;">​</a></h3><p>❌ &quot;Nie einen Schuss verfehlen&quot; (unmöglich) ✅ „Genauigkeit innerhalb von 8 Wochen um 10 % verbessern“ (anspruchsvoll, aber realistisch)</p><h3 id="r-–-relevant" tabindex="-1">R – Relevant <a class="header-anchor" href="#r-–-relevant" aria-label="Permalink to &quot;R – Relevant&quot;">​</a></h3><p>❌ &quot;Einen Marathon laufen&quot; (nicht direkt verwandt) ✅ „Verbessert Gleichgewicht und Stabilität für bessere Würfe“ (unterstützt dein Spiel)</p><h3 id="t-–-zeitgebunden" tabindex="-1">T – Zeitgebunden <a class="header-anchor" href="#t-–-zeitgebunden" aria-label="Permalink to &quot;T – Zeitgebunden&quot;">​</a></h3><p>❌ „Eines Tages wird es mir besser gehen.“ ✅ „Bis zum 15. März werde ich Folgendes erreichen…“</p><h2 id="torbeispiele-fur-petanque" tabindex="-1">Torbeispiele für Pétanque <a class="header-anchor" href="#torbeispiele-fur-petanque" aria-label="Permalink to &quot;Torbeispiele für Pétanque&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Typ</th><th>Schlechtes Tor</th><th>SMART-Ziel</th></tr></thead><tbody><tr><td>Ergebnis</td><td>&quot;Mehr gewinnen&quot;</td><td>„Das Halbfinale beim Frühlingsturnier erreichen“</td></tr><tr><td>Leistung</td><td>&quot;Besser punkten&quot;</td><td>&quot;Erreichen Sie 70 % der Punkte innerhalb von 50 cm auf eine Entfernung von 8 m.&quot;</td></tr><tr><td>Verfahren</td><td>&quot;Übe mehr&quot;</td><td>&quot;Absolviere 3 gezielte Trainingseinheiten pro Woche&quot;</td></tr></tbody></table><h2 id="große-ziele-in-ihre-einzelteile-zerlegen" tabindex="-1">Große Ziele in ihre Einzelteile zerlegen <a class="header-anchor" href="#große-ziele-in-ihre-einzelteile-zerlegen" aria-label="Permalink to &quot;Große Ziele in ihre Einzelteile zerlegen&quot;">​</a></h2><p>Große Ziele können überwältigend wirken. Teilen Sie sie in kleinere Teile auf:</p><h3 id="beispiel-„gewinne-die-vereinsmeisterschaft-in-12-monaten" tabindex="-1">Beispiel: „Gewinne die Vereinsmeisterschaft (in 12 Monaten)“ <a class="header-anchor" href="#beispiel-„gewinne-die-vereinsmeisterschaft-in-12-monaten" aria-label="Permalink to &quot;Beispiel: „Gewinne die Vereinsmeisterschaft (in 12 Monaten)“&quot;">​</a></h3><p><strong>Jahresziel:</strong> Vereinsmeisterschaft gewinnen</p><p><strong>Quartalsziele:</strong></p><ul><li>Frage 1: Verbesserung der Schussgenauigkeit auf 75 %</li><li>Frage 2: Entwickeln Sie eine konsistente Vorbereitungsroutine vor dem Schuss.</li><li>Frage 3: Drucksituationen meistern</li><li>Q4: Höchstleistung und Wettkampfvorbereitung</li></ul><p><strong>Monatliche Ziele (1. Quartal):</strong></p><ul><li>Monat 1: Ausgangslage festlegen, Schwächen identifizieren</li><li>Monat 2: Schwerpunkt auf der Aufnahmetechnik</li><li>Monat 3: Den Druck beim Schießtraining erhöhen</li></ul><p><strong>Wöchentliche Ziele (Monat 2):</strong></p><ul><li>Woche 1: 3 Schießsitzungen, Videoanalyse</li><li>Woche 2: Arbeit an dem identifizierten technischen Problem</li><li>Woche 3: Die Distanz schrittweise erhöhen</li><li>Woche 4: Fortschritte testen, Plan anpassen</li></ul><h2 id="ziele-mit-ihrem-„warum-verbinden" tabindex="-1">Ziele mit Ihrem „Warum“ verbinden <a class="header-anchor" href="#ziele-mit-ihrem-„warum-verbinden" aria-label="Permalink to &quot;Ziele mit Ihrem „Warum“ verbinden&quot;">​</a></h2><p>Ziele funktionieren besser, wenn sie mit einer tieferen Motivation verbunden sind.</p><p>Frage dich selbst:</p><ul><li>Warum möchte ich das erreichen?</li><li>Was wird das für mich bedeuten?</li><li>Wie werde ich mich fühlen, wenn ich Erfolg habe?</li><li>Was treibt mich an, mich zu verbessern?</li></ul><p>Notieren Sie Ihre Antworten. Kehren Sie darauf zurück, wenn Ihre Motivation nachlässt.</p><h2 id="in-diesem-abschnitt" tabindex="-1">In diesem Abschnitt <a class="header-anchor" href="#in-diesem-abschnitt" aria-label="Permalink to &quot;In diesem Abschnitt&quot;">​</a></h2><ul><li><strong><a href="/en/education/goals/smart-goals">SMART Goals im Detail</a></strong> – Ein detaillierter Einblick in die Erstellung effektiver Ziele</li><li><strong><a href="/en/education/goals/planning">Erstellung deines Trainingsplans</a></strong> – Ziele in die Tat umsetzen</li></ul><h2 id="zusammenfassung-regeln-zur-zielsetzung" tabindex="-1">Zusammenfassung: Regeln zur Zielsetzung <a class="header-anchor" href="#zusammenfassung-regeln-zur-zielsetzung" aria-label="Permalink to &quot;Zusammenfassung: Regeln zur Zielsetzung&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regel Nr. 1: Die Kontrollregel</p><p><strong>Konzentrieren Sie sich auf Prozessziele (das, was Sie kontrollieren können) und nicht auf Ergebnisziele.</strong> Prozessziele führen zu Leistungszielen, die wiederum zu Ergebniszielen führen.</p></div><div class="tip custom-block"><p class="custom-block-title">Regel Nr. 2: Die SMART-Regel</p><p><strong>Ziele müssen spezifisch, messbar, erreichbar, relevant und terminiert sein.</strong> Vage Ziele führen zu vagen Ergebnissen. SMART-Ziele führen zu Fortschritt.</p></div><div class="tip custom-block"><p class="custom-block-title">Regel Nr. 3: Die Aufschlüsselungsregel</p><p><strong>Große Ziele erfordern vierteljährliche, monatliche und wöchentliche Meilensteine.</strong> Große Ziele lassen sich in kleine, umsetzbare Schritte unterteilen, die Sie diese Woche erledigen können.</p></div><div class="tip custom-block"><p class="custom-block-title">Regel Nr. 4: Die Verbindungsregel</p><p>Verbinde deine Ziele mit deinem tieferen „Warum“. Wenn die Motivation nachlässt, ist es dein „Warum“, das dich am Laufen hält.</p></div><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Ein Ziel ohne Plan ist nur ein Wunsch.</p></blockquote><p>Setzen Sie sich klare Ziele. Unterteilen Sie diese in kleinere Schritte. Konzentrieren Sie sich auf das, was Sie beeinflussen können. Verfolgen Sie Ihre Fortschritte.</p>',40))])}]]);export{u as __pageData,d as default};
